<script setup lang="ts">
import {computed} from 'vue';
import {ThumbsUp,MoreHorizontal,ChevronDown,ChevronUp} from 'lucide-vue-next';
import TreeholeImages from './TreeholeImages.vue';
import TreeholeAvatar from './TreeholeAvatar.vue';
import {treeholeTimestamp} from '../domain/treeholePresentation';
import type {TreeholeComment} from '../services/treehole';
const props=defineProps<{comment:TreeholeComment;busy:boolean;locked:boolean;expanded?:boolean;more?:boolean;loading?:boolean;pendingLikes?:Record<string,boolean>}>();
defineEmits<{image:[comment:TreeholeComment,index:number];reply:[comment:TreeholeComment];like:[comment:TreeholeComment];menu:[comment:TreeholeComment];expand:[];collapse:[]}>();
const shown=computed(()=>props.expanded?props.comment.replies:props.comment.replies?.slice(0,2));
function replyName(c:TreeholeComment){return c.replyTo===props.comment.id?'':props.comment.replies?.find(x=>x.id===c.replyTo)?.author.name||'同学';}
</script>
<template>
 <article class="th-comment" :class="{'is-deleted':comment.deleted}"><TreeholeAvatar :name="comment.author.name" :url="comment.author.avatar?.url" :anonymous="comment.author.anonymous" :size="36"/><div class="th-comment-content"><header><div><strong>{{comment.author.name}}<em v-if="comment.isOriginalPoster">楼主</em><em v-else-if="comment.author.mine">我</em></strong><small>{{treeholeTimestamp(comment.createdAt)}}</small></div><button v-if="!comment.deleted" class="th-comment-like" :aria-label="comment.liked?'取消评论点赞':'点赞评论'" :aria-pressed="!!comment.liked" :disabled="busy||pendingLikes?.[comment.id]" @click="$emit('like',comment)"><ThumbsUp :size="17" :fill="comment.liked?'currentColor':'none'"/>{{comment.likeCount||''}}</button><button v-if="!comment.deleted" class="th-comment-menu" aria-label="评论操作" :disabled="busy" @click="$emit('menu',comment)"><MoreHorizontal :size="17"/></button></header><p v-if="comment.body!=='[图片]'||!comment.images?.length" class="th-comment-body">{{comment.body}}</p><TreeholeImages v-if="!comment.deleted" :images="comment.images||[]" :post-id="comment.postId" @open="$emit('image',comment,$event)"/><button v-if="!comment.deleted&&!locked" class="th-reply" :disabled="busy" @click="$emit('reply',comment)">回复</button><div v-if="comment.replies?.length||(comment.replyCount||0)>0" class="th-replies"><div v-for="child in shown" :key="child.id" class="th-nested-reply"><button class="th-reply-text" :class="{'is-preview':!expanded}" :disabled="busy||locked||child.deleted" @click="$emit('reply',child)"><strong>{{child.author.name}}<em v-if="child.isOriginalPoster">楼主</em></strong><span v-if="replyName(child)" class="th-reply-quote"> 回复 {{replyName(child)}}</span>{{child.body==='[图片]'&&child.images?.length?'':'：'+child.body}}</button><TreeholeImages v-if="!child.deleted" :images="child.images||[]" :post-id="child.postId" @open="$emit('image',child,$event)"/><div v-if="expanded" class="th-reply-meta"><small>{{treeholeTimestamp(child.createdAt)}}</small><button v-if="expanded&&!child.deleted" :aria-label="child.liked?'取消评论点赞':'点赞评论'" :aria-pressed="!!child.liked" :disabled="busy||pendingLikes?.[child.id]" @click="$emit('like',child)"><ThumbsUp :size="13" :fill="child.liked?'currentColor':'none'"/>{{child.likeCount||''}}</button><button v-if="!child.deleted" aria-label="回复操作" :disabled="busy" @click="$emit('menu',child)"><MoreHorizontal :size="16"/></button></div></div><button v-if="!expanded||more" class="th-expand-replies" :disabled="busy||loading" @click="$emit('expand')">{{loading?'正在加载…':expanded?'加载更多回复':'全部 '+comment.replyCount+' 条回复'}}<ChevronDown :size="15"/></button><button v-if="expanded" class="th-collapse-replies" :disabled="busy||loading" @click="$emit('collapse')">收起回复<ChevronUp :size="14"/></button></div></div></article>
</template>
<style scoped>
.th-comment{display:flex;align-items:flex-start;gap:10px;padding:23px 0;border-bottom:1px solid var(--color-divider)}.th-comment:last-child{border:0}.th-comment-content{flex:1;min-width:0}header{display:flex;align-items:flex-start;gap:5px}header>div{flex:1;min-width:0}strong{font-weight:600;font-size:14px;overflow-wrap:anywhere}em{font-style:normal;font-size:10px;padding:1px 4px;margin-left:5px;background:#44494e;color:white;border-radius:3px;white-space:nowrap}small{font-size:max(12px,.75rem);color:var(--color-muted);display:block;margin-top:5px}.th-comment-like,.th-comment-menu{display:flex;align-items:center;justify-content:center;gap:4px;min-height:44px;color:var(--color-muted);font-size:12px}.th-comment-menu{width:36px;margin-right:-6px}button[aria-pressed=true]{color:var(--color-primary)}.th-comment-body{font-size:16px;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 1px}.is-deleted .th-comment-body{color:var(--color-muted)}.th-reply{min-height:44px;color:var(--color-muted);font-size:12px;padding:0 6px 0 0}.th-replies{background:var(--color-bg);border-radius:10px;padding:10px 12px 0;margin-top:7px}.th-nested-reply{padding:3px 0 5px}.th-reply-text{text-align:left;font-size:14px;line-height:1.75;overflow-wrap:anywhere;white-space:pre-wrap;width:100%;min-height:0;padding:0}.th-reply-text strong{color:#3b6689;font-size:14px;font-weight:500}.th-reply-quote{font-size:13px;color:var(--color-muted)}.th-reply-meta{display:flex;align-items:center;gap:9px;color:var(--color-muted);min-height:36px}.th-reply-meta small{flex:1;margin:0;font-size:max(11px,.6875rem)}.th-reply-meta button{display:flex;align-items:center;gap:3px;min-height:36px;font-size:10px;padding:0 3px}.th-expand-replies,.th-collapse-replies{display:flex;gap:5px;align-items:center;justify-content:center;width:100%;min-height:39px;color:var(--color-muted);font-size:12px;border-top:1px solid var(--color-divider)}.th-collapse-replies{font-size:11px;min-height:34px}
.th-reply-text.is-preview{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.th-nested-reply:has(.is-preview){padding:5px 0 7px}
.th-comment-content :deep(.th-images){max-width:270px;margin:8px 0}.th-comment-content :deep(.th-images.single){max-width:180px}.th-comment-content :deep(.th-images.single button){max-height:180px}
</style>
